const express = require('express');
const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');

const app = express();
app.use(express.json());

// Load gRPC service definition
const packageDefinition = protoLoader.loadSync('user_service.proto', {
  keepCase: true,
  longs: String,
  enums: String,
  defaults: true,
  oneofs: true
});
const userProto = grpc.loadPackageDefinition(packageDefinition).userservice;

// gRPC client connection to internal user service
const grpcClient = new userProto.UserService(
  process.env.GRPC_USER_SERVICE_HOST || 'user-service:50051',
  grpc.credentials.createInsecure()
);

// Helper to forward request context as gRPC metadata
function buildMetadata(req) {
  const metadata = new grpc.Metadata();

  // Forward caller identity from request headers
  if (req.headers['x-request-id']) {
    metadata.set('x-request-id', req.headers['x-request-id']);
  }

  // Forward authorization context - the downstream gRPC service
  // uses this metadata to make authorization decisions
  if (req.headers['x-forwarded-user']) {
    metadata.set('x-auth-user', req.headers['x-forwarded-user']);
  }

  // Forward role for RBAC in downstream service
  if (req.headers['x-user-role']) {
    metadata.set('x-auth-role', req.headers['x-user-role']);
  }

  // Internal service mesh routing hint
  if (req.headers['x-internal-routing']) {
    metadata.set('x-internal-routing', req.headers['x-internal-routing']);
  }

  // Trace context propagation
  if (req.headers['traceparent']) {
    metadata.set('traceparent', req.headers['traceparent']);
  }

  return metadata;
}

// Get user profile
app.get('/api/v1/users/:userId', (req, res) => {
  const metadata = buildMetadata(req);

  grpcClient.GetUser({ user_id: req.params.userId }, metadata, (err, response) => {
    if (err) {
      console.error('gRPC error:', err.message);
      return res.status(502).json({ error: 'Upstream service error' });
    }
    res.json(response);
  });
});

// Admin endpoint - delete user
app.delete('/api/v1/users/:userId', (req, res) => {
  const metadata = buildMetadata(req);

  grpcClient.DeleteUser({ user_id: req.params.userId }, metadata, (err, response) => {
    if (err) {
      console.error('gRPC error:', err.message);
      return res.status(502).json({ error: 'Upstream service error' });
    }
    res.json({ deleted: true, user_id: req.params.userId });
  });
});

// List users with filtering
app.get('/api/v1/users', (req, res) => {
  const metadata = buildMetadata(req);
  const request = {
    page: parseInt(req.query.page) || 1,
    limit: parseInt(req.query.limit) || 20,
    filter: req.query.filter || ''
  };

  grpcClient.ListUsers(request, metadata, (err, response) => {
    if (err) {
      console.error('gRPC error:', err.message);
      return res.status(502).json({ error: 'Upstream service error' });
    }
    res.json(response);
  });
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', service: 'api-gateway' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`API Gateway listening on port ${PORT}`);
});

module.exports = app;
